import re

def parse_json_object(text: str) -> dict | None:
    pattern = r'\{(?:[^{}]|(?:\{[^{}]*\}))*\}'
    match = re.search(pattern, text)
    if match:
        try:
            import json
            return json.loads(match.group())
        except (json.JSONDecodeError, ValueError):
            return None
    return None
